from typing import Dict, Any
from document_models import ExtractedDocument, NormalizedExpense

def normalize_expense(extracted_data: Dict[str, Any]) -> Dict[str, Any]:
    document_type = extracted_data.get("document_type")
    extracted_doc = None
    if document_type == "invoice":
        if "invoices" in extracted_data and extracted_data["invoices"]:
            invoice_data = extracted_data["invoices"][0]
            extracted_doc = ExtractedDocument(**invoice_data)
    elif document_type == "receipt":
        if "receipt" in extracted_data:
            receipt_data = extracted_data["receipt"]
            extracted_doc = ExtractedDocument(**receipt_data)

    if not extracted_doc:
        raise ValueError("No extracted document found for normalization.")

    normalized_expense = NormalizedExpense(
        document_type=document_type,
        vendor_name=extracted_doc.vendor or extracted_doc.merchant,
        transaction_date=extracted_doc.date,
        total_amount=float(extracted_doc.total) if extracted_doc.total else None,
        tax_amount=float(extracted_doc.tax) if extracted_doc.tax else None,
        currency="USD", # Assuming USD for now, can be extracted later
        line_items=[item.dict() for item in (extracted_doc.line_items or extracted_doc.items)],
    )

    return {"normalized_expense": normalized_expense.dict()}

import boto3
from typing import Dict, Any, List
from document_models import NormalizedExpense
from document_client import load_config, get_aws_client

def validate_document_fields(normalized_expense_data: Dict[str, Any]) -> Dict[str, Any]:
    config = load_config()
    region = config.get("aws_region")
    comprehend_language_code = config.get("aws_comprehend_language_code")

    if not all([region, comprehend_language_code]):
        raise ValueError("AWS region or Comprehend language code is not configured.")

    client = get_aws_client("comprehend", region)

    normalized_expense = NormalizedExpense(**normalized_expense_data["normalized_expense"])

    validation_results = {"is_valid": True, "errors": []}

    # Example validation: Check if vendor name is present
    if not normalized_expense.vendor_name:
        validation_results["is_valid"] = False
        validation_results["errors"].append({"field": "vendor_name", "message": "Vendor name is missing."})

    # Example validation using AWS Comprehend for transaction date
    if normalized_expense.transaction_date:
        try:
            response = client.detect_entities(
                Text=normalized_expense.transaction_date,
                LanguageCode=comprehend_language_code
            )
            date_entities = [entity for entity in response["Entities"] if entity["Type"] == "DATE"]
            if not date_entities:
                validation_results["is_valid"] = False
                validation_results["errors"].append({"field": "transaction_date", "message": "Transaction date is not recognized as a valid date."})
        except Exception as e:
            validation_results["is_valid"] = False
            validation_results["errors"].append({"field": "transaction_date", "message": f"Comprehend entity detection failed: {str(e)}"})        
    else:
        validation_results["is_valid"] = False
        validation_results["errors"].append({"field": "transaction_date", "message": "Transaction date is missing."})

    # Add more validation logic as needed

    return {"validation_results": validation_results}

import google.generativeai as genai
from typing import Dict, Any
from document_models import NormalizedExpense
from document_client import load_config

def summarize_invoice_fields(normalized_expense_data: Dict[str, Any]) -> Dict[str, Any]:
    config = load_config()
    model_name = config.get("google_generative_model_name")

    if not model_name:
        raise ValueError("Google Generative AI model name is not configured.")

    # Ensure GOOGLE_API_KEY environment variable is set for genai
    if "GOOGLE_API_KEY" not in os.environ:
        print("Warning: GOOGLE_API_KEY environment variable not set for Google Generative AI.")

    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel(model_name)

    normalized_expense = NormalizedExpense(**normalized_expense_data["normalized_expense"])

    summary_prompt = f"""
    Summarize the following expense record:
    Document Type: {normalized_expense.document_type}
    Vendor Name: {normalized_expense.vendor_name}
    Transaction Date: {normalized_expense.transaction_date}
    Total Amount: {normalized_expense.total_amount}
    Tax Amount: {normalized_expense.tax_amount}
    Line Items: {normalized_expense.line_items}

    Provide a concise summary in a single paragraph.
    """

    response = model.generate_content(summary_prompt)
    summary = response.text

    return {"summary": summary}
